func (f *Factory) WithTinkerbellClients(clusterConfigFile string) *Factory {
	return f.WithTinkClient(clusterConfigFile).WithPbnjClient(clusterConfigFile)
}

func (f *Factory) WithTinkClient(clusterConfigFile string) *Factory {
	f.WithExecutableBuilder()

	f.buildSteps = append(f.buildSteps, func(ctx context.Context) error {
		if f.dependencies.TinkerbellClients.ProviderTinkClient != nil {
			return nil
		}

		tinkerbellDatacenterConfig, err := v1alpha1.GetTinkerbellDatacenterConfig(clusterConfigFile)
		if err != nil {
			return err
		}
		f.dependencies.TinkerbellClients.ProviderTinkClient = f.executableBuilder.BuildTinkExecutable(tinkerbellDatacenterConfig.Spec.TinkerbellCertURL, tinkerbellDatacenterConfig.Spec.TinkerbellGRPCAuth)
		return nil
	})

	return f
}

func (f *Factory) WithPbnjClient(clusterConfigFile string) *Factory {
	f.buildSteps = append(f.buildSteps, func(ctx context.Context) error {
		if f.dependencies.TinkerbellClients.ProviderPbnjClient != nil {
			return nil
		}

		tinkerbellDatacenterConfig, err := v1alpha1.GetTinkerbellDatacenterConfig(clusterConfigFile)
		if err != nil {
			return err
		}

		pbnjClient, err := pbnj.NewPBNJClient(tinkerbellDatacenterConfig.Spec.TinkerbellPBnJGRPCAuth)
		if err != nil {
			return err
		}
		f.dependencies.TinkerbellClients.ProviderPbnjClient = pbnjClient
		return nil
	})

	return f
}

